/// Lesson sections for the info page — never shown on the practice screen.
const List<TechniqueSection> grooveHalftimeShuffleLesson = [
  TechniqueSection(
    title: "Why it matters",
    body:
        "The half-time shuffle is one of the hardest and most famous grooves on the kit: a shuffle hi-hat, the backbeat only on 3, and ghost notes on the middle triplet notes that fill every gap. When it sits, it rolls like nothing else; when it does not, everyone hears it.",
  ),
  TechniqueSection(
    title: "How to play it",
    body:
        "Right hand on the hi-hat: the first and last note of every triplet, never the middle. Left hand: a soft ghost on the middle triplet note of every beat, except on 3, where it plays the loud backbeat on the beat and a ghost on the \"let\". The kick plays 1 and the \"let\" of 2. Ghosts at the lowest height the stick can manage.",
  ),
  TechniqueSection(
    title: "Practice tips",
    body:
        "Line 2 drops the ghosts so you hear the frame: shuffle hat, kick, backbeat on 3. Line 3 makes the ghosts denser, also on the \"let\" with the hat. Line 4 adds a kick on the \"let\" of 4, line 5 opens the hi-hat on the \"let\" of 4, line 6 moves the right hand to the ride while the foot closes the hat on 2 and 4, line 7 plays the backbeat as a flam, line 8 begins with a crash. Practise the hands alone until the ghosts are even.",
  ),
  TechniqueSection(
    title: "Where you hear it",
    body:
        "Bernard Purdie on Steely Dan \"Babylon Sisters\" (the Purdie shuffle), Jeff Porcaro on Toto \"Rosanna\", John Bonham on Led Zeppelin \"Fool in the Rain\".",
  ),
];
